SELECT

FROM patient_exercise_record
WHERE id = #{id}
  AND patient_id = #{patientId}
  AND is_deleted = 0
LIMIT 1

SELECT

FROM patient_exercise_record
WHERE patient_id = #{patientId}
  AND is_deleted = 0
ORDER BY started_at DESC, id DESC
LIMIT #{limit}

SELECT

FROM patient_exercise_record
WHERE patient_id = #{patientId}
  AND is_deleted = 0
  AND started_at >= #{fromTime}
ORDER BY started_at DESC, id DESC

mapper.update:
UPDATE patient_exercise_record
SET is_deleted = 1
WHERE id = #{id}
  AND patient_id = #{patientId}
  AND is_deleted = 0
